-- MENAJER ONLINE 013: büyük kulüplere gerçek forma renkleri (kariyer ve hızlı maç)
do $$
declare d text;
begin
  d := pg_get_functiondef('public._club_team(uuid,text,text,uuid)'::regprocedure);
  if position('returning id into t;' in d) = 0 then raise exception '_club_team beklenen haliyle değil'; end if;
  execute replace(d, 'returning id into t;', $r$returning id into t;
  -- bilinen kulüplerin gerçek renkleri
  declare kk jsonb := '{"Galatasaray SK": ["#a90432", "#fdb913", "halves"], "Fenerbahçe SK": ["#0a1f5c", "#ffed00", "stripes"], "Beşiktaş JK": ["#111111", "#ffffff", "halves"], "Trabzonspor": ["#7b1e3a", "#5fa8d3", "stripes"], "Medipol Başakşehir FK": ["#f26522", "#1e2a5a", "plain"], "Samsunspor": ["#e30613", "#ffffff", "plain"], "Çaykur Rizespor": ["#0a7d3b", "#1d4fa0", "halves"], "Kocaelispor": ["#0a7d3b", "#111111", "stripes"], "Arsenal": ["#ef0107", "#ffffff", "plain"], "Manchester City": ["#6cabdd", "#ffffff", "plain"], "Liverpool": ["#c8102e", "#ffffff", "plain"], "Aston Villa": ["#670e36", "#95bfe5", "plain"], "Tottenham Hotspur": ["#f5f5f5", "#132257", "plain"], "Chelsea": ["#034694", "#ffffff", "plain"], "Newcastle United": ["#111111", "#ffffff", "stripes"], "Nottingham Forest": ["#dd0000", "#ffffff", "plain"], "Manchester United": ["#da291c", "#ffffff", "plain"], "Everton": ["#003399", "#ffffff", "plain"], "West Ham United": ["#7a263a", "#1bb1e7", "plain"], "Atlético Madrid": ["#cb3524", "#ffffff", "stripes"], "Real Madrid": ["#f5f5f5", "#febe10", "plain"], "FC Barcelona": ["#a50044", "#004d98", "stripes"], "Athletic Club": ["#ee2523", "#ffffff", "stripes"], "Real Sociedad": ["#0067b1", "#ffffff", "stripes"], "Villarreal CF": ["#ffe667", "#005187", "plain"], "RC Celta": ["#8ac3ee", "#e31c23", "plain"], "Girona FC": ["#cd2534", "#ffffff", "stripes"], "Sevilla FC": ["#f5f5f5", "#d81e05", "plain"], "Real Betis": ["#00954c", "#ffffff", "stripes"], "Paris Saint-Germain": ["#004170", "#da291c", "plain"], "Stade Rennais FC": ["#e13327", "#111111", "plain"], "Olympique de Marseille": ["#f5f5f5", "#2faee0", "plain"], "AS Monaco": ["#e7192b", "#ffffff", "sash"], "OGC Nice": ["#c8102e", "#111111", "stripes"], "Lille OSC": ["#e01e13", "#1b2d5b", "plain"], "Olympique Lyonnais": ["#f5f5f5", "#da001a", "plain"], "FC Bayern München": ["#dc052d", "#ffffff", "plain"], "Borussia Dortmund": ["#fde100", "#111111", "plain"], "Bayer 04 Leverkusen": ["#e32221", "#111111", "plain"], "RB Leipzig": ["#f5f5f5", "#dd0741", "plain"], "VfL Wolfsburg": ["#65b32e", "#ffffff", "plain"], "Eintracht Frankfurt": ["#e1000f", "#111111", "plain"], "SC Freiburg": ["#e2001a", "#111111", "plain"], "Borussia Mönchengladbach": ["#f5f5f5", "#111111", "plain"], "Inter": ["#0068a8", "#111111", "stripes"], "Napoli": ["#12a0d7", "#ffffff", "plain"], "Juventus": ["#f5f5f5", "#111111", "stripes"], "AC Milan": ["#fb090b", "#111111", "stripes"], "Roma": ["#8e1f2f", "#f0bc42", "plain"], "Atalanta": ["#1e71b8", "#111111", "stripes"], "Lazio": ["#87d8f7", "#ffffff", "plain"], "Bologna": ["#1a2f48", "#a21c26", "halves"], "Fiorentina": ["#482e92", "#ffffff", "plain"], "PSV": ["#ed1c24", "#ffffff", "stripes"], "Feyenoord": ["#e60000", "#ffffff", "halves"], "Ajax": ["#f5f5f5", "#d2122e", "sash"], "AZ Alkmaar": ["#db0021", "#ffffff", "plain"], "FC Twente": ["#e30613", "#ffffff", "plain"], "Sporting CP": ["#008057", "#ffffff", "hoops"], "SL Benfica": ["#e83030", "#ffffff", "plain"], "FC Porto": ["#003893", "#ffffff", "stripes"], "Sporting Clube de Braga": ["#dc0d15", "#ffffff", "plain"], "Club Brugge KV": ["#0078c1", "#111111", "stripes"], "KRC Genk": ["#003c8c", "#ffffff", "plain"], "Union Saint-Gilloise": ["#fdd200", "#1e3a8a", "plain"], "RSC Anderlecht": ["#4e2d84", "#ffffff", "plain"], "KAA Gent": ["#0060a8", "#ffffff", "plain"], "Standard de Liège": ["#d71920", "#ffffff", "plain"]}'::jsonb -> p_club;
  begin
    if kk is not null then
      update public.teams set color1 = kk->>0, color2 = kk->>1, kit = kit || jsonb_build_object('pattern', kk->>2) where id = t;
    end if;
  end;$r$);
end $$;
-- mevcut kariyer ve hızlı maç takımları
update public.teams t set color1 = k.value->>0, color2 = k.value->>1, kit = t.kit || jsonb_build_object('pattern', k.value->>2)
  from jsonb_each('{"Galatasaray SK": ["#a90432", "#fdb913", "halves"], "Fenerbahçe SK": ["#0a1f5c", "#ffed00", "stripes"], "Beşiktaş JK": ["#111111", "#ffffff", "halves"], "Trabzonspor": ["#7b1e3a", "#5fa8d3", "stripes"], "Medipol Başakşehir FK": ["#f26522", "#1e2a5a", "plain"], "Samsunspor": ["#e30613", "#ffffff", "plain"], "Çaykur Rizespor": ["#0a7d3b", "#1d4fa0", "halves"], "Kocaelispor": ["#0a7d3b", "#111111", "stripes"], "Arsenal": ["#ef0107", "#ffffff", "plain"], "Manchester City": ["#6cabdd", "#ffffff", "plain"], "Liverpool": ["#c8102e", "#ffffff", "plain"], "Aston Villa": ["#670e36", "#95bfe5", "plain"], "Tottenham Hotspur": ["#f5f5f5", "#132257", "plain"], "Chelsea": ["#034694", "#ffffff", "plain"], "Newcastle United": ["#111111", "#ffffff", "stripes"], "Nottingham Forest": ["#dd0000", "#ffffff", "plain"], "Manchester United": ["#da291c", "#ffffff", "plain"], "Everton": ["#003399", "#ffffff", "plain"], "West Ham United": ["#7a263a", "#1bb1e7", "plain"], "Atlético Madrid": ["#cb3524", "#ffffff", "stripes"], "Real Madrid": ["#f5f5f5", "#febe10", "plain"], "FC Barcelona": ["#a50044", "#004d98", "stripes"], "Athletic Club": ["#ee2523", "#ffffff", "stripes"], "Real Sociedad": ["#0067b1", "#ffffff", "stripes"], "Villarreal CF": ["#ffe667", "#005187", "plain"], "RC Celta": ["#8ac3ee", "#e31c23", "plain"], "Girona FC": ["#cd2534", "#ffffff", "stripes"], "Sevilla FC": ["#f5f5f5", "#d81e05", "plain"], "Real Betis": ["#00954c", "#ffffff", "stripes"], "Paris Saint-Germain": ["#004170", "#da291c", "plain"], "Stade Rennais FC": ["#e13327", "#111111", "plain"], "Olympique de Marseille": ["#f5f5f5", "#2faee0", "plain"], "AS Monaco": ["#e7192b", "#ffffff", "sash"], "OGC Nice": ["#c8102e", "#111111", "stripes"], "Lille OSC": ["#e01e13", "#1b2d5b", "plain"], "Olympique Lyonnais": ["#f5f5f5", "#da001a", "plain"], "FC Bayern München": ["#dc052d", "#ffffff", "plain"], "Borussia Dortmund": ["#fde100", "#111111", "plain"], "Bayer 04 Leverkusen": ["#e32221", "#111111", "plain"], "RB Leipzig": ["#f5f5f5", "#dd0741", "plain"], "VfL Wolfsburg": ["#65b32e", "#ffffff", "plain"], "Eintracht Frankfurt": ["#e1000f", "#111111", "plain"], "SC Freiburg": ["#e2001a", "#111111", "plain"], "Borussia Mönchengladbach": ["#f5f5f5", "#111111", "plain"], "Inter": ["#0068a8", "#111111", "stripes"], "Napoli": ["#12a0d7", "#ffffff", "plain"], "Juventus": ["#f5f5f5", "#111111", "stripes"], "AC Milan": ["#fb090b", "#111111", "stripes"], "Roma": ["#8e1f2f", "#f0bc42", "plain"], "Atalanta": ["#1e71b8", "#111111", "stripes"], "Lazio": ["#87d8f7", "#ffffff", "plain"], "Bologna": ["#1a2f48", "#a21c26", "halves"], "Fiorentina": ["#482e92", "#ffffff", "plain"], "PSV": ["#ed1c24", "#ffffff", "stripes"], "Feyenoord": ["#e60000", "#ffffff", "halves"], "Ajax": ["#f5f5f5", "#d2122e", "sash"], "AZ Alkmaar": ["#db0021", "#ffffff", "plain"], "FC Twente": ["#e30613", "#ffffff", "plain"], "Sporting CP": ["#008057", "#ffffff", "hoops"], "SL Benfica": ["#e83030", "#ffffff", "plain"], "FC Porto": ["#003893", "#ffffff", "stripes"], "Sporting Clube de Braga": ["#dc0d15", "#ffffff", "plain"], "Club Brugge KV": ["#0078c1", "#111111", "stripes"], "KRC Genk": ["#003c8c", "#ffffff", "plain"], "Union Saint-Gilloise": ["#fdd200", "#1e3a8a", "plain"], "RSC Anderlecht": ["#4e2d84", "#ffffff", "plain"], "KAA Gent": ["#0060a8", "#ffffff", "plain"], "Standard de Liège": ["#d71920", "#ffffff", "plain"]}'::jsonb) k, public.games g
 where g.id = t.game_id and k.key = t.name and (g.settings ? 'career' or g.settings ? 'sandbox');
